const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions (approx. UCI Coastal Sage near Irvine, CA)
    const station = ee.Geometry.Point([-117.842, 33.649]);
    const roi = station.buffer(5000); // 5 km buffer to ensure at least 1 pixel
    const periods = [
      {label: 'Jan2013', start: '2013-01-01', end: '2013-02-01'},
      {label: 'May2013', start: '2013-05-01', end: '2013-06-01'}
    ];

    // Helper to compute monthly mean soil moisture with fallback
    async function getMonthlySM(start, end) {
      // Primary: ERA5-Land hourly, volumetric soil water layer 1 (0-7 cm)
      const primary = {
        id: 'ECMWF/ERA5_LAND/HOURLY',
        band: 'volumetric_soil_water_layer_1',
        scale: 9000,
        unit: 'm3/m3',
        convert: function(img){ return img; }
      };
      // Fallback: GLDAS Noah 3-hourly 0-10 cm (kg/m^2); convert to m3/m3 by /100
      const fallback = {
        id: 'NASA/GLDAS/V021/NOAH/G025/T3H',
        band: 'SoilMoi0_10cm_inst',
        scale: 25000,
        unit: 'm3/m3',
        convert: function(img){ return img.divide(100); }
      };

      async function tryDataset(ds) {
        let col = ee.ImageCollection(ds.id).select(ds.band).filterDate(start, end).filterBounds(roi);
        const size = await col.size().getInfo();
        if (size === 0) return {status: 'C1', size: 0, dataset: ds.id};
        const meanImg = ds.convert(col.mean());
        const meanDict = await meanImg.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: roi,
          scale: ds.scale,
          maxPixels: 1e9,
          bestEffort: true
        }).getInfo();
        const countDict = await meanImg.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: roi,
          scale: ds.scale,
          maxPixels: 1e9,
          bestEffort: true
        }).getInfo();
        const val = meanDict ? meanDict[ds.band] : null;
        const count = countDict ? countDict[ds.band] : 0;
        if (!count || count === 0) return {status: 'C2', size, dataset: ds.id};
        if (val === null || typeof val !== 'number' || !isFinite(val)) return {status: 'C3', size, dataset: ds.id};
        // Basic plausibility for volumetric soil moisture
        if (val < 0 || val > 1.2) return {status: 'C3', size, dataset: ds.id};
        return {status: 'OK', size, val, count, dataset: ds.id};
      }

      let res = await tryDataset(primary);
      if (res.status === 'C1') {
        res = await tryDataset(fallback);
      }
      return res;
    }

    const jan = await getMonthlySM(periods[0].start, periods[0].end);
    const may = await getMonthlySM(periods[1].start, periods[1].end);

    // Print concise evidence
    console.log(`Geometry: UCI Coastal Sage approx (5 km buffer)`);
    console.log(`Jan2013 Images: ${jan.size} [Dataset: ${jan.dataset}]`);
    console.log(`May2013 Images: ${may.size} [Dataset: ${may.dataset}]`);

    // Handle data issues
    if (jan.status === 'C1' || may.status === 'C1') {
      console.log(`Status: Empty Collection for at least one period`);
      console.log('C1');
      return;
    }
    if (jan.status === 'C2' || may.status === 'C2') {
      console.log(`Status: No Valid Pixels after processing`);
      console.log('C2');
      return;
    }
    if (jan.status === 'C3' || may.status === 'C3') {
      console.log(`Status: Calculation Failure (null/invalid)`);
      console.log('C3');
      return;
    }
    // If datasets differ between months, still comparable (both in m3/m3); note it
    if (jan.dataset !== may.dataset) {
      console.log(`Note: Different datasets used (converted to m3/m3): Jan=${jan.dataset}, May=${may.dataset}`);
    }

    console.log(`Jan2013 Mean SM (m3/m3): ${jan.val.toFixed(3)} | Pixels: ${jan.count}`);
    console.log(`May2013 Mean SM (m3/m3): ${may.val.toFixed(3)} | Pixels: ${may.count}`);
    const diff = jan.val - may.val;
    console.log(`Difference (Jan - May): ${diff.toFixed(3)} m3/m3`);

    // Final Decision
    const answer = diff > 0 ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
